CREATE OR REPLACE FUNCTION public.apply_account_deletion_privacy_manifest(p_job uuid, p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j public.account_deletion_jobs;actions jsonb;a jsonb;t text;c text;target text;field text;op text;values_to_match uuid[];tables text[];aliases jsonb;changed integer;total integer:=0;blocked integer:=0;allowed text[];
BEGIN
 j:=public.account_deletion_assert_claim(p_job,p_token);
 IF NOT public.account_deletion_rule_allowed(j.policy_version,'personal.erase') THEN RETURN jsonb_build_object('state','review');END IF;
 SELECT parameters->'privacyManifest' INTO actions FROM public.account_deletion_action_rule WHERE policy_version=j.policy_version AND scope='personal.erase';
 IF actions IS NULL OR jsonb_typeof(actions)<>'array' THEN RETURN jsonb_build_object('state','review','reasonCode','privacy_manifest_required');END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('kind',kind,'token',token)),'[]') INTO aliases FROM public.account_deletion_alias WHERE job_id=j.id;
 SELECT coalesce(array_agg(DISTINCT 'public.'||(value->>'table')),'{}') INTO tables FROM jsonb_array_elements(actions);
 PERFORM public.account_deletion_authorize_write(j.id,p_token,'personal.erase',tables,ARRAY['UPDATE']);
 FOR a IN SELECT value FROM jsonb_array_elements(actions) LOOP
  t:=a->>'table';c:=a->>'column';target:=a->>'target';field:=a->>'field';op:=a->>'action';
  IF t LIKE 'account_deletion_%' OR t IN ('reward_transactions','reward_redemptions','fulfilment','ride_session','route_tracking','ride_reward_configuration_snapshot','ride_reward_settlement') OR (t IN ('fulfilment_event','partner_validation','platform_audit_record') AND NOT public.account_deletion_rule_allowed(j.policy_version,'appendonly.privacy')) THEN blocked:=blocked+1;CONTINUE;END IF;
  IF field NOT IN ('metadata','before_values','after_values','payload','body','message','content','text','comment','notes','description','contact_email','contact_phone','email','phone','avatar_url','device_context','device_id','push_token','account_notes','request_payload','response_payload','route_payload','export_options','schedule','trace_id','error','filename','error_message','name','reason','emergency_contact','emergency_phone','actor_email','previous_state','resulting_state','reason','note') THEN RAISE EXCEPTION 'unclassified personal field';END IF;
  IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=t AND column_name=field AND udt_name IN ('text','jsonb','varchar')) THEN RAISE EXCEPTION 'privacy field schema drift';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.account_deletion_barrier_binding WHERE schema_name='public' AND table_name=t AND column_name=c AND identity_kind=CASE target WHEN 'user' THEN 'user' WHEN 'rider' THEN 'rider' ELSE NULL END)
   AND NOT(t='user' AND c='id' AND target='user') AND NOT(target='admin_users' AND EXISTS(SELECT 1 FROM pg_catalog.pg_constraint fk JOIN pg_catalog.pg_attribute att ON att.attrelid=fk.conrelid AND att.attnum=fk.conkey[1] WHERE fk.contype='f' AND cardinality(fk.conkey)=1 AND cardinality(fk.confkey)=1 AND fk.conrelid=to_regclass(format('public.%I',t)) AND fk.confrelid='public.admin_users'::regclass AND att.attname=c)) THEN RAISE EXCEPTION 'privacy principal binding required';END IF;
  values_to_match:=CASE target WHEN 'user' THEN ARRAY[j.user_id] WHEN 'rider' THEN ARRAY(SELECT id FROM public.rider WHERE user_id=j.user_id) WHEN 'admin_users' THEN ARRAY(SELECT id FROM public.admin_users WHERE user_id=j.user_id) ELSE NULL END;
  IF values_to_match IS NULL THEN RAISE EXCEPTION 'unsupported privacy ownership adapter';END IF;
  BEGIN
   IF op='redact_alias_mentions' THEN
    IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=t AND column_name=field AND udt_name='jsonb') THEN
     EXECUTE format('UPDATE public.%I SET %I=public.account_deletion_redact_projection(%I,$2) WHERE %I=ANY($1) AND %I IS DISTINCT FROM public.account_deletion_redact_projection(%I,$2)',t,field,field,c,field,field) USING values_to_match,aliases;
    ELSE
     EXECUTE format('UPDATE public.%I SET %I=public.account_deletion_redact_projection(to_jsonb(%I),$2)#>>''{}'' WHERE %I=ANY($1) AND to_jsonb(%I) IS DISTINCT FROM public.account_deletion_redact_projection(to_jsonb(%I),$2)',t,field,field,c,field,field) USING values_to_match,aliases;
    END IF;
   ELSIF op='json_keep_fields' THEN
    SELECT coalesce(array_agg(value),'{}') INTO allowed FROM jsonb_array_elements_text(a->'fields');
    EXECUTE format('UPDATE public.%I r SET %I=(SELECT coalesce(jsonb_object_agg(key,value),''{}''::jsonb) FROM jsonb_each(r.%I) WHERE key=ANY($2)) WHERE %I=ANY($1)',t,field,field,c) USING values_to_match,allowed;
   ELSIF op='redacted' THEN
    IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=t AND column_name=field AND udt_name IN ('text','varchar')) THEN RAISE EXCEPTION 'redacted text field required';END IF;
    EXECUTE format('UPDATE public.%I SET %I=$2 WHERE %I=ANY($1)',t,field,c) USING values_to_match,'Deleted account';
   ELSIF op='null' THEN
    IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=t AND column_name=field AND is_nullable='NO') THEN blocked:=blocked+1;CONTINUE;END IF;
    EXECUTE format('UPDATE public.%I SET %I=NULL WHERE %I=ANY($1) AND %I IS NOT NULL',t,field,c,field) USING values_to_match;
   ELSE RAISE EXCEPTION 'unsupported privacy projection';END IF;
   GET DIAGNOSTICS changed=ROW_COUNT;total:=total+changed;
  EXCEPTION WHEN raise_exception OR check_violation OR not_null_violation THEN blocked:=blocked+1;END;
 END LOOP;
 IF blocked>0 THEN INSERT INTO public.account_deletion_review(job_id,category,reason_code,owner_capability,due_at) VALUES(j.id,'residual_erasure','privacy_field_disposition_requires_adapter','privacy.deletion.compliance.review',clock_timestamp()+interval '1 day') ON CONFLICT DO NOTHING;END IF;
 INSERT INTO public.account_deletion_audit(job_id,event_code) VALUES(j.id,'approved_privacy_field_projection_executed');
 RETURN jsonb_build_object('state',CASE WHEN blocked>0 THEN 'review' ELSE 'confirmed' END,'changedRows',total,'blockedActions',blocked);
END $function$

CREATE OR REPLACE FUNCTION public.assign_admin_route(p_actor uuid, p_route uuid, p_riders uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE caps jsonb; template public.route; v_rider_id uuid; assignment_id uuid; inserted_riders uuid[]:='{}'; requested integer;
BEGIN
  IF coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
  SELECT public.ops_employee_capabilities(a.role) INTO caps FROM public.admin_users a JOIN public."user" u ON u.id=a.user_id WHERE a.user_id=p_actor AND u.status='active';
  IF NOT coalesce(caps ? 'routes.write',false) THEN RAISE EXCEPTION 'Unauthorized route assignment' USING ERRCODE='42501'; END IF;
  SELECT * INTO template FROM public.route WHERE id=p_route FOR UPDATE;
  IF template.id IS NULL THEN RAISE EXCEPTION 'Route not found'; END IF;
  SELECT count(DISTINCT x) INTO requested FROM unnest(p_riders) x;
  IF requested=0 THEN RAISE EXCEPTION 'Riders required'; END IF;
  FOR v_rider_id IN SELECT DISTINCT x FROM unnest(p_riders) x ORDER BY x LOOP
    IF NOT EXISTS(SELECT 1 FROM public.rider WHERE id=v_rider_id) THEN RAISE EXCEPTION 'Rider not found'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.rider_route rr WHERE rr.route_id=p_route AND rr.rider_id=v_rider_id) THEN
      INSERT INTO public.rider_route(rider_id,route_id,campaign_id,status,assigned_at,updated_at)
        VALUES(v_rider_id,p_route,template.campaign_id,'assigned',now(),now()) RETURNING id INTO assignment_id;
      INSERT INTO public.platform_audit_record(actor_user_id,principal_type,capability,target_entity_type,target_entity_id,resulting_state,correlation_id,reason)
        VALUES(p_actor,'admin','routes.write','rider_route',assignment_id::text,'{"action":"rider_route.create"}',assignment_id::text,'entity_initiator');
      inserted_riders:=array_append(inserted_riders,v_rider_id);
    END IF;
  END LOOP;
  RETURN jsonb_build_object('assignedCount',cardinality(inserted_riders),'skippedCount',requested-cardinality(inserted_riders),'riderIds',to_jsonb(inserted_riders));
END $function$

CREATE OR REPLACE FUNCTION public.assign_employee_role(p_actor uuid, p_user uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE caps jsonb; v_public_role text; prior_role text;
BEGIN
  IF coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
  SELECT public.ops_employee_capabilities(a.role) INTO caps FROM public.admin_users a
    JOIN public."user" u ON u.id=a.user_id WHERE a.user_id=p_actor AND u.status='active';
  IF NOT coalesce(caps ? CASE WHEN p_role IN ('super_admin','security_admin') THEN 'users.role.approve' ELSE 'users.role.assign' END,false) THEN
    RAISE EXCEPTION 'Unauthorized role assignment' USING ERRCODE='42501';
  END IF;
  SELECT role::text INTO v_public_role FROM public."user" WHERE id=p_user FOR UPDATE;
  SELECT role INTO prior_role FROM public.admin_users WHERE user_id=p_user;
  IF v_public_role IS NULL THEN RAISE EXCEPTION 'User not found'; END IF;
  IF p_role IN ('rider','advertiser') AND v_public_role=p_role THEN RETURN; END IF;
  IF p_actor=p_user AND NOT(public.ops_employee_capabilities(prior_role) @> public.ops_employee_capabilities(p_role)) THEN
    RAISE EXCEPTION 'Self-escalation is not permitted' USING ERRCODE='42501';
  END IF;
  IF p_role IS NULL OR p_role IN ('admin','moderator','support','compliance_officer','government')
      OR jsonb_array_length(public.ops_employee_capabilities(p_role))=0 THEN
    RAISE EXCEPTION 'Invalid employee role; product conversion requires its own workflow';
  END IF;
  IF v_public_role NOT IN ('admin','super_admin','moderator','support','gov')
     OR EXISTS(SELECT 1 FROM public.rider WHERE user_id=p_user)
     OR EXISTS(SELECT 1 FROM public.advertiser WHERE user_id=p_user) THEN
    RAISE EXCEPTION 'Product identities cannot be reclassified through employee assignment';
  END IF;
  -- Do not revive an incomplete provisioning reservation through a role edit.
  IF EXISTS(SELECT 1 FROM public.employee_provisioning WHERE user_id=p_user AND state<>'complete') THEN
    RAISE EXCEPTION 'Finish employee provisioning before changing its role';
  END IF;
  UPDATE public."user" SET role='admin',updated_at=now() WHERE id=p_user;
  INSERT INTO public.admin_users(user_id,email,role,created_by)
    SELECT id,email,p_role,p_actor FROM public."user" WHERE id=p_user
    ON CONFLICT(user_id) DO UPDATE SET role=excluded.role,updated_at=now();
  IF prior_role IS DISTINCT FROM p_role THEN
    INSERT INTO public.platform_audit_record(actor_user_id,principal_type,capability,target_entity_type,target_entity_id,previous_state,resulting_state,correlation_id,reason)
      VALUES(p_actor,'admin',CASE WHEN p_role IN ('super_admin','security_admin') THEN 'users.role.approve' ELSE 'users.role.assign' END,
        'user',p_user::text,jsonb_build_object('role',prior_role),jsonb_build_object('role',p_role),gen_random_uuid()::text,'admin_employee_role_assignment_v1');
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.authorize_account_deletion_managed_dispatch(p_job uuid, p_token uuid, p_method text, p_path text, p_body jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j public.account_deletion_jobs;prefix text;object_name text;bucket text;
BEGIN
 j:=public.account_deletion_assert_claim(p_job,p_token);
 IF NOT public.account_deletion_activation_authorized(p_job,p_token) OR p_method<>'DELETE' THEN RETURN false;END IF;
 IF p_path='/auth/v1/admin/users/'||j.user_id::text THEN
  RETURN EXISTS(SELECT 1 FROM public.account_deletion_operation o WHERE o.job_id=j.id AND o.lease_token=p_token
   AND o.kind='auth_delete' AND o.state='prepared' AND o.dispatched_at IS NOT NULL AND o.resource=jsonb_build_object('userId',j.user_id));
 END IF;
 IF p_path NOT LIKE '/storage/v1/object/%' OR jsonb_typeof(p_body->'prefixes') IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_body->'prefixes')<>1 THEN RETURN false;END IF;
 bucket:=substring(p_path from length('/storage/v1/object/')+1);
 object_name:=p_body->'prefixes'->>0;
 RETURN EXISTS(SELECT 1 FROM public.account_deletion_external_resource r JOIN public.account_deletion_operation o
 ON o.job_id=r.job_id AND o.operation_key='external:'||r.id::text WHERE r.job_id=j.id AND r.kind='storage_remove'
 AND r.locator->>'bucketId'=bucket AND r.locator->>'name'=object_name AND o.lease_token=p_token
 AND o.state='prepared' AND o.dispatched_at IS NOT NULL AND o.resource->>'classificationId'=r.id::text
 AND o.resource->>'objectId'=r.source_id);
END $function$

CREATE OR REPLACE FUNCTION public.claim_my_held_ride_recovery(p_approval uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s public.ride_session;st public.ride_reward_settlement;g public.held_ride_recovery_approval;owner uuid;e jsonb;n integer;
BEGIN
 -- Same lock order as the existing executor: session, rider, settlement.
 SELECT * INTO s FROM public.ride_session WHERE id='fb5df08c-06ad-4b25-ac0d-81419226e3a4' FOR UPDATE;
 SELECT user_id INTO owner FROM public.rider WHERE id=s.rider_id FOR UPDATE;
 IF owner IS NULL OR owner IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ride not owned';END IF;
 SELECT * INTO st FROM public.ride_reward_settlement WHERE ride_session_id=s.id FOR UPDATE;
 SELECT * INTO g FROM public.held_ride_recovery_approval WHERE approval_id=p_approval FOR UPDATE;
 IF g.approval_id IS NULL OR g.state<>'approved' OR g.expires_at<=clock_timestamp() OR g.approved_by=g.proposed_by
  OR owner IN (g.proposed_by,g.approved_by) THEN RAISE EXCEPTION 'valid unconsumed independent approval required';END IF;
 PERFORM 1 FROM public.admin_users WHERE user_id IN (g.proposed_by,g.approved_by) ORDER BY user_id FOR SHARE;
 GET DIAGNOSTICS n=ROW_COUNT;IF n<>2 THEN RAISE EXCEPTION 'operator authority revoked';END IF;
 IF NOT public.held_ride_recovery_has_capability(g.proposed_by,'rides.settlement.recovery.request')
  OR NOT public.held_ride_recovery_has_capability(g.approved_by,'rides.settlement.recovery.review') THEN RAISE EXCEPTION 'operator authority revoked';END IF;
 e:=public.held_ride_recovery_evidence();
 IF e->>'eligible' IS DISTINCT FROM 'true' OR e->>'evidenceDigest' IS DISTINCT FROM g.evidence_digest THEN RAISE EXCEPTION 'recovery evidence changed';END IF;
 PERFORM public.account_deletion_assert_writable(owner);
 UPDATE public.held_ride_recovery_approval SET state='consumed',claimed_at=clock_timestamp() WHERE approval_id=p_approval;
 UPDATE public.ride_reward_settlement SET status='calculating',attempts=attempts+1,lease_token=gen_random_uuid(),lease_until=clock_timestamp()+interval '5 minutes',
  award_status=NULL,last_error=NULL,updated_at=clock_timestamp() WHERE ride_session_id=s.id RETURNING * INTO st;
 UPDATE public.held_ride_recovery_approval SET claim_audit_id=public.audit_held_ride_recovery(owner,p_approval,'claimed',g.reason,jsonb_build_object('historicalAttempts',23,'attempts',st.attempts,'leaseUntil',st.lease_until)) WHERE approval_id=p_approval;
 RETURN to_jsonb(st);
END $function$

CREATE OR REPLACE FUNCTION public.execute_account_deletion_database_core(p_job uuid, p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j public.account_deletion_jobs;manifest jsonb;a jsonb;values_to_match uuid[];tables text[];t text;c text;target text;op text;r record;ids uuid[];n integer;total integer:=0;blocked integer:=0;policy_fields text[];proof jsonb;
BEGIN
 j:=public.account_deletion_assert_claim(p_job,p_token);
 IF EXISTS(SELECT 1 FROM public.account_deletion_operation WHERE job_id=j.id AND operation_key='database.erase:v1' AND state='confirmed') THEN RETURN jsonb_build_object('state','confirmed');END IF;
 IF NOT public.account_deletion_rule_allowed(j.policy_version,'personal.erase') THEN RETURN jsonb_build_object('state','review','reasonCode','database_erasure_approval_required');END IF;
 SELECT parameters->'executionManifest' INTO manifest FROM public.account_deletion_action_rule WHERE policy_version=j.policy_version AND scope='personal.erase';
 IF manifest IS NULL OR jsonb_typeof(manifest)<>'array' THEN RETURN jsonb_build_object('state','review','reasonCode','database_erasure_manifest_required');END IF;
 -- This is an ownership inventory, not an alias search. It survives erasure for
 -- checkpoint recovery. All derived IDs require an actual principal binding.
 INSERT INTO public.account_deletion_subject_inventory VALUES(j.id,'user',j.user_id) ON CONFLICT DO NOTHING;
 INSERT INTO public.account_deletion_subject_inventory SELECT j.id,'rider',id FROM public.rider WHERE user_id=j.user_id ON CONFLICT DO NOTHING;
 INSERT INTO public.account_deletion_subject_inventory SELECT j.id,'admin_users',id FROM public.admin_users WHERE user_id=j.user_id ON CONFLICT DO NOTHING;
 INSERT INTO public.account_deletion_subject_inventory SELECT j.id,'ride_session',s.id FROM public.ride_session s JOIN public.rider ri ON ri.id=s.rider_id WHERE ri.user_id=j.user_id ON CONFLICT DO NOTHING;
 INSERT INTO public.account_deletion_subject_inventory SELECT j.id,'route_tracking',s.id FROM public.route_tracking s JOIN public.rider ri ON ri.id=s.rider_id WHERE ri.user_id=j.user_id ON CONFLICT DO NOTHING;
 IF EXISTS(SELECT 1 FROM public.ride_session s JOIN public.rider ri ON ri.id=s.rider_id LEFT JOIN public.ride_reward_settlement st ON st.ride_session_id=s.id WHERE ri.user_id=j.user_id AND st.status IS DISTINCT FROM 'settled') THEN RETURN jsonb_build_object('state','review','reasonCode','pending_settlement_preserved');END IF;
 IF EXISTS(SELECT 1 FROM public.rider_reward_balance b JOIN public.rider ri ON ri.id=b.rider_id WHERE ri.user_id=j.user_id AND b.points_balance<>0) THEN RETURN jsonb_build_object('state','review','reasonCode','wallet_disposition_required');END IF;
 IF EXISTS(SELECT 1 FROM public.reward_redemptions d JOIN public.rider ri ON ri.id=d.rider_id WHERE ri.user_id=j.user_id AND d.status IN ('requested','approved')) THEN RETURN jsonb_build_object('state','review','reasonCode','valid_redemption_continuation_required');END IF;
 IF EXISTS(SELECT 1 FROM public.fulfilment f JOIN public.rider ri ON ri.id=f.rider_id WHERE ri.user_id=j.user_id AND f.state NOT IN ('completed','refunded','reversed','cancelled','failed','expired')) THEN RETURN jsonb_build_object('state','review','reasonCode','valid_fulfilment_continuation_required');END IF;
 IF EXISTS(SELECT 1 FROM public.reward_transactions rt JOIN public.rider ri ON ri.id=rt.rider_id WHERE ri.user_id=j.user_id AND rt.campaign_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.account_deletion_campaign_checkpoint c WHERE c.job_id=j.id AND c.campaign_id=rt.campaign_id AND c.state='confirmed')) THEN RETURN jsonb_build_object('state','review','reasonCode','campaign_reporting_disposition_required');END IF;
 SELECT coalesce(array_agg(DISTINCT 'public.'||(value->>'table')),'{}') INTO tables FROM jsonb_array_elements(manifest);
 PERFORM public.account_deletion_authorize_write(j.id,p_token,'personal.erase',tables,ARRAY['DELETE','UPDATE']);
 -- Every action is explicit and catalog-bound. Shared entity deletion is forbidden.
 -- Archive actions retain only approved scalar fields under independently approved
 -- purpose/period controls. They do not insert reporting facts or replacement riders.
 FOR a IN SELECT value FROM jsonb_array_elements(manifest) LOOP
  t:=a->>'table';c:=a->>'column';target:=a->>'target';op:=a->>'action';
  IF t LIKE 'account_deletion_%' OR t IN ('campaign','organisation','community_ride','campaign_accessory_inventory_item','partner','suggested_routes','hot_zones') AND op<>'detach_reference' THEN RAISE EXCEPTION 'shared entity erasure forbidden';END IF;
  IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=t AND column_name=c AND udt_name='uuid') THEN RAISE EXCEPTION 'manifest schema drift';END IF;
  IF NOT (c='id' AND t=target AND target IN ('user','rider','admin_users')) AND NOT EXISTS(
   SELECT 1 FROM pg_catalog.pg_constraint k JOIN pg_catalog.pg_class child ON child.oid=k.conrelid JOIN pg_catalog.pg_namespace ns ON ns.oid=child.relnamespace JOIN pg_catalog.pg_attribute att ON att.attrelid=k.conrelid AND att.attnum=k.conkey[1] JOIN pg_catalog.pg_class parent ON parent.oid=k.confrelid
   WHERE ns.nspname='public' AND child.relname=t AND att.attname=c AND k.contype='f' AND cardinality(k.conkey)=1 AND parent.relname=target
  ) AND NOT EXISTS(SELECT 1 FROM public.account_deletion_barrier_binding WHERE schema_name='public' AND table_name=t AND column_name=c AND identity_kind=CASE target WHEN 'user' THEN 'user' WHEN 'rider' THEN 'rider' ELSE NULL END) THEN RAISE EXCEPTION 'manifest ownership binding required';END IF;
  SELECT coalesce(array_agg(row_id),'{}') INTO values_to_match FROM public.account_deletion_subject_inventory WHERE job_id=j.id AND table_name=target;
  IF op IN ('delete_owned','archive_owned') THEN
   IF t='organisation_membership' AND EXISTS(SELECT 1 FROM public.organisation_membership m WHERE m.user_id=j.user_id) THEN
    -- Membership removal belongs to the continuity/capability/consent adapter.
    -- A privacy manifest is not permission to remove the last organisation owner.
    blocked:=blocked+1;CONTINUE;
   END IF;
   IF c NOT IN ('id','user_id','rider_id','admin_user_id','employee_user_id','session_id','ride_session_id','route_tracking_id','assignment_id','fulfilment_id','redemption_id','ticket_id','ticketid','support_ticket_id') OR (c='id' AND t<>target) THEN RAISE EXCEPTION 'authorship is not destructive ownership';END IF;
   IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=t AND column_name='id' AND udt_name='uuid') THEN
    EXECUTE format('SELECT coalesce(array_agg(id),''{}'') FROM public.%I WHERE %I=ANY($1)',t,c) INTO ids USING values_to_match;
   ELSIF op='delete_owned' THEN ids:='{}';
   ELSE RAISE EXCEPTION 'explicit composite ownership adapter required';END IF;
   -- Add exclusively owned child keys for ordered leaf dispositions. Manifest
   -- may include capture_owned actions before child deletion when order requires it.
   INSERT INTO public.account_deletion_subject_inventory SELECT j.id,t,x FROM unnest(ids) x ON CONFLICT DO NOTHING;
   IF public.account_deletion_has_children(t,c,values_to_match) THEN blocked:=blocked+1;CONTINUE;END IF;
   IF t IN ('reward_transactions','reward_redemptions','fulfilment','fulfilment_event','partner_validation','campaign_assignment_events','community_ride_change_log','platform_audit_record') AND op<>'archive_owned' THEN RAISE EXCEPTION 'business evidence disposition required';END IF;
   IF op='archive_owned' THEN
    IF EXISTS(SELECT 1 FROM public.account_deletion_hold WHERE job_id=j.id AND category IN (a->>'category','all') AND released_at IS NULL) THEN blocked:=blocked+1;CONTINUE;END IF;
    IF NOT public.account_deletion_rule_allowed(j.policy_version,'evidence.restrict') THEN RAISE EXCEPTION 'business evidence approval required';END IF;
    FOR r IN EXECUTE format('SELECT id,to_jsonb(r) data FROM public.%I r WHERE %I=ANY($1) FOR UPDATE',t,c) USING values_to_match LOOP
     PERFORM public.capture_account_deletion_case(j.id,p_token,a->>'category',t,r.id,r.data);
    END LOOP;
   END IF;
   EXECUTE format('DELETE FROM public.%I WHERE %I=ANY($1)',t,c) USING values_to_match;
  ELSIF op='capture_owned' THEN
   IF c NOT IN ('user_id','rider_id','admin_user_id','employee_user_id','session_id','ride_session_id','route_tracking_id','assignment_id','fulfilment_id','redemption_id','ticket_id','ticketid','support_ticket_id') THEN RAISE EXCEPTION 'destructive ownership binding required';END IF;
   EXECUTE format('SELECT coalesce(array_agg(id),''{}'') FROM public.%I WHERE %I=ANY($1)',t,c) INTO ids USING values_to_match;
   INSERT INTO public.account_deletion_subject_inventory SELECT j.id,t,x FROM unnest(ids) x ON CONFLICT DO NOTHING;CONTINUE;
  ELSIF op='detach_reference' THEN
   IF c NOT IN ('created_by','updated_by','auth_user_id','admin_user_id','changed_by_user_id','changed_by','actor_user_id','created_by_user_id','assigned_by','invited_by','accepted_by','revoked_by','resolved_by','verified_by','granted_by_user_id') THEN RAISE EXCEPTION 'ownership detachment requires independent continuity adapter';END IF;
   IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=t AND column_name=c AND is_nullable='NO') THEN blocked:=blocked+1;CONTINUE;END IF;
   EXECUTE format('UPDATE public.%I SET %I=NULL WHERE %I=ANY($1)',t,c,c) USING values_to_match;
  ELSE RAISE EXCEPTION 'unsupported erasure disposition';END IF;
  GET DIAGNOSTICS n=ROW_COUNT;total:=total+n;
 END LOOP;
 -- Root removal is a consequence of explicit dispositions, never an implicit
 -- cascade. No checkpoint is issued while operational principals remain.
 IF blocked>0 OR EXISTS(SELECT 1 FROM public.rider WHERE user_id=j.user_id) OR EXISTS(SELECT 1 FROM public.admin_users WHERE user_id=j.user_id) OR EXISTS(SELECT 1 FROM public."user" WHERE id=j.user_id) THEN
  INSERT INTO public.account_deletion_review(job_id,category,reason_code,owner_capability,due_at) VALUES(j.id,'residual_erasure','restricted_dependency_disposition_required','privacy.deletion.compliance.review',clock_timestamp()+interval '1 day') ON CONFLICT DO NOTHING;
  RETURN jsonb_build_object('state','review','changedRows',total,'blockedActions',blocked);
 END IF;
 proof:=public.verify_account_deletion_residual(j.id,p_token);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(proof->'residuals') x WHERE x->>'schema'<>'auth') THEN RETURN jsonb_build_object('state','review','reasonCode','database_residuals_remain');END IF;
 INSERT INTO public.account_deletion_operation(job_id,operation_key,lease_token,state,confirmed_at,result_code) VALUES(j.id,'database.erase:v1',p_token,'confirmed',clock_timestamp(),'application_catalog_absence_verified');
 INSERT INTO public.account_deletion_audit(job_id,event_code) VALUES(j.id,'database_erasure_independently_verified');
 RETURN jsonb_build_object('state','confirmed','changedRows',total);
END $function$

CREATE OR REPLACE FUNCTION public.guard_employee_auth_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.employee_provisioning; product public.product_provisioning;
BEGIN
  -- GoTrue can apply custom app_metadata AFTER inserting auth.users. Resolve the
  -- already-committed intent by UUID, not by insertion-time metadata timing.
  SELECT * INTO r FROM public.employee_provisioning WHERE user_id=NEW.id;
  IF r.user_id IS NOT NULL THEN
    IF r.state<>'reserved' OR r.email<>lower(NEW.email) THEN
      RAISE EXCEPTION 'Invalid employee provisioning reservation';
    END IF;
    NEW.banned_until := now()+interval '100 years';
    NEW.raw_app_meta_data:=coalesce(NEW.raw_app_meta_data,'{}') || jsonb_build_object('employee_provisioning_id',NEW.id::text);
    NEW.raw_user_meta_data := coalesce(NEW.raw_user_meta_data,'{}') || jsonb_strip_nulls(jsonb_build_object(
      'server_assigned_role','admin','full_name',r.input->>'name','phone',r.input->>'phone'));
  ELSE
    SELECT * INTO product FROM public.product_provisioning WHERE user_id=NEW.id;
    IF product.user_id IS NOT NULL THEN
      IF product.input->>'role' NOT IN ('rider','advertiser') OR product.state<>'reserved' OR product.email<>lower(NEW.email) THEN
        RAISE EXCEPTION 'Invalid product provisioning reservation';
      END IF;
      NEW.banned_until:=now()+interval '100 years';
      NEW.raw_app_meta_data:=coalesce(NEW.raw_app_meta_data,'{}') || jsonb_build_object('admin_product_provisioning',
        jsonb_build_object('actor',product.actor_id::text,'fingerprint',product.fingerprint));
      NEW.raw_user_meta_data:=coalesce(NEW.raw_user_meta_data,'{}') || jsonb_strip_nulls(jsonb_build_object(
        'server_assigned_role',product.input->>'role','full_name',product.input->>'name',
        'phone',product.input->>'phone','city',product.input->>'city','country',product.input->>'country',
        'companyName',product.input->'advertiserProfile'->>'companyName','language',product.input->>'languagePreference',
        'timezone',product.input->'advertiserProfile'->>'timezone'));
    ELSIF NEW.raw_app_meta_data ?| ARRAY['employee_provisioning_id','admin_product_provisioning'] THEN
      RAISE EXCEPTION 'Provisioning marker without a reservation';
    ELSIF coalesce(NEW.raw_user_meta_data,'{}') ? 'server_assigned_role' AND
       coalesce(NEW.raw_user_meta_data->>'server_assigned_role','') NOT IN ('rider','advertiser') THEN
      -- Explicit invalid/operational metadata must never reach the legacy
      -- handler's catch-all Rider fallback. Employee grants require a reservation.
      RAISE EXCEPTION 'Operational account roles require authorized employee provisioning';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.join_community_ride(p_community_ride_id uuid, p_rider_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ride        RECORD;
  v_active_cnt  INTEGER;
BEGIN
 PERFORM public.assert_active_account();
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'auth_required');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.rider r
    WHERE r.id = p_rider_id
      AND r.user_id = auth.uid()
  ) AND NOT EXISTS (
    SELECT 1 FROM public.admin_users au
    WHERE au.user_id = auth.uid()
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
  END IF;

  SELECT id, status, max_participants, is_public
    INTO v_ride
    FROM public.community_ride
   WHERE id = p_community_ride_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'ride_not_found');
  END IF;

  IF NOT v_ride.is_public THEN
    RETURN jsonb_build_object('success', false, 'error', 'ride_not_public');
  END IF;

  IF v_ride.status NOT IN ('upcoming', 'active') THEN
    RETURN jsonb_build_object('success', false, 'error', 'ride_not_joinable');
  END IF;

  SELECT COUNT(*)
    INTO v_active_cnt
    FROM public.community_ride_participant
   WHERE community_ride_id = p_community_ride_id
     AND status = 'joined';

  IF v_active_cnt >= v_ride.max_participants THEN
    RETURN jsonb_build_object('success', false, 'error', 'ride_full');
  END IF;

  INSERT INTO public.community_ride_participant
    (community_ride_id, rider_id, status, joined_at)
  VALUES
    (p_community_ride_id, p_rider_id, 'joined', NOW())
  ON CONFLICT (community_ride_id, rider_id)
    DO UPDATE SET status = 'joined', joined_at = NOW();

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_employee_profile_pending()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.raw_app_meta_data ? 'employee_provisioning_id' THEN
    IF EXISTS(SELECT 1 FROM public.rider WHERE user_id=NEW.id) THEN
      RAISE EXCEPTION 'Employee bootstrap must not create Rider';
    END IF;
    UPDATE public."user" SET status='pending' WHERE id=NEW.id AND role='admin';
    IF NOT FOUND THEN RAISE EXCEPTION 'Invalid employee public profile bootstrap'; END IF;
  ELSIF NEW.raw_app_meta_data ? 'admin_product_provisioning' THEN
    UPDATE public."user" SET status='pending' WHERE id=NEW.id AND role::text=(SELECT input->>'role' FROM public.product_provisioning WHERE user_id=NEW.id);
    IF NOT FOUND THEN RAISE EXCEPTION 'Invalid product public profile bootstrap'; END IF;
    UPDATE public.rider SET status='inactive' WHERE user_id=NEW.id;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.ops_assert_capability(p_capability text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE actor uuid:=auth.uid(); role_name text;
BEGIN
 PERFORM public.assert_active_account();
 IF coalesce((SELECT (value->>'enforceAdminMfa')::boolean FROM public.platform_settings WHERE key='security'),true) AND coalesce(current_setting('request.jwt.claims',true),'{}')::jsonb->>'aal' IS DISTINCT FROM 'aal2' THEN
  RAISE EXCEPTION 'MFA required' USING ERRCODE='42501'; END IF;
 SELECT role::text INTO role_name FROM public.admin_users WHERE user_id=actor;
 IF role_name IS NULL OR NOT (public.ops_employee_capabilities(role_name) ? p_capability) THEN
  RAISE EXCEPTION 'Capability required' USING ERRCODE='42501'; END IF;
 RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION public.ops_queue_notifications(p_operation uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE actor uuid; job public.ops_notification_send;
BEGIN
 actor:=public.ops_assert_capability('notifications.send');
 IF p_operation IS NULL OR length(trim(coalesce(p_payload->>'title',''))) NOT BETWEEN 1 AND 200 OR length(trim(coalesce(p_payload->>'message',''))) NOT BETWEEN 1 AND 10000 OR p_payload->>'type' NOT IN ('campaign_assigned','campaign_completed','route_assigned','route_completed','system','reward','status') OR p_payload->>'target' NOT IN ('all','role','userIds') OR jsonb_typeof(p_payload->'respectPreferences') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Invalid notification request' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_operation::text,8));
 SELECT * INTO job FROM public.ops_notification_send WHERE id=p_operation FOR UPDATE;
 IF FOUND THEN
  IF job.actor_user_id<>actor OR job.payload<>p_payload THEN RAISE EXCEPTION 'Operation conflict' USING ERRCODE='40001'; END IF;
  RETURN public.ops_notification_status(p_operation);
 END IF;
 IF p_payload->>'target'='role' AND nullif(p_payload->>'role','') IS NULL OR p_payload->>'target'='userIds' AND (jsonb_typeof(p_payload->'userIds') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload->'userIds')=0) THEN RAISE EXCEPTION 'Audience required' USING ERRCODE='22023'; END IF;
 INSERT INTO public.ops_notification_send(id,actor_user_id,payload) VALUES(p_operation,actor,p_payload);
 -- No PostgREST row cap. Preference-query failure rolls back the entire operation.
 INSERT INTO public.ops_notification_recipient(operation,user_id)
 SELECT p_operation,u.id FROM public."user" u LEFT JOIN public.user_preferences pref ON pref.user_id=u.id
 WHERE u.status::text='active' AND (p_payload->>'target'='all' OR p_payload->>'target'='role' AND u.role::text=p_payload->>'role' OR p_payload->>'target'='userIds' AND (p_payload->'userIds') ? u.id::text)
 AND (NOT (p_payload->>'respectPreferences')::boolean OR coalesce(pref.notifications,true));
 PERFORM public.ops_audit('notifications.send','notification_send',p_operation::text,NULL,jsonb_build_object('audience',p_payload->>'target','counts',public.ops_notification_status(p_operation)),'Notification send queued',p_operation);
 RETURN public.ops_notification_status(p_operation);
END $function$

CREATE OR REPLACE FUNCTION public.provision_employee(p_actor uuid, p_input jsonb, p_phase text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.employee_provisioning; actor_role text; caps jsonb; requested text:=p_input->>'role';
BEGIN
  IF coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
  SELECT a.role INTO actor_role FROM public.admin_users a JOIN public."user" u ON u.id=a.user_id
    WHERE a.user_id=p_actor AND u.status='active';
  caps:=public.ops_employee_capabilities(actor_role);
  IF NOT coalesce(caps ? 'users.manage',false) OR NOT coalesce(caps ?
      CASE WHEN requested IN ('super_admin','security_admin') THEN 'users.role.approve' ELSE 'users.role.assign' END,false) THEN
    RAISE EXCEPTION 'Unauthorized employee role assignment' USING ERRCODE='42501';
  END IF;
  -- Canonical roles are the generated template contract; do not accept aliases
  -- for new employees, or put owner/manager/staff/viewer in this role domain.
  IF requested IS NULL OR requested IN ('admin','moderator','support','compliance_officer','government')
     OR jsonb_array_length(public.ops_employee_capabilities(requested))=0
     OR p_input->>'status' IS NULL OR p_input->>'status' NOT IN ('active','inactive','pending')
     OR coalesce(btrim(p_input->>'name'),'')='' OR coalesce(p_input->>'email','') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     OR p_input->>'email'<>lower(btrim(p_input->>'email'))
     OR p_input ?| ARRAY['organisationId','organisation_id','membershipRole','bundleKey'] THEN
    RAISE EXCEPTION 'Invalid employee provisioning contract';
  END IF;
  IF p_phase NOT IN ('reserve','persist','complete') THEN RAISE EXCEPTION 'Invalid provisioning phase'; END IF;
  -- All operations for an email, including concurrent first submissions, serialize.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_input->>'email',68));
  SELECT * INTO r FROM public.employee_provisioning WHERE email=p_input->>'email' FOR UPDATE;
  IF r.user_id IS NULL THEN
    IF p_phase<>'reserve' THEN RAISE EXCEPTION 'Provisioning reservation missing'; END IF;
    IF EXISTS(SELECT 1 FROM auth.users WHERE lower(email)=p_input->>'email') THEN
      RAISE EXCEPTION 'Existing account: use its authorized invitation workflow; creation cannot reclassify it';
    END IF;
    INSERT INTO public.employee_provisioning(email,actor_id,input) VALUES(p_input->>'email',p_actor,p_input) RETURNING * INTO r;
  END IF;
  IF r.actor_id<>p_actor OR r.input<>p_input THEN RAISE EXCEPTION 'Conflicting provisioning request; original reservation preserved'; END IF;
  IF r.state IN ('ready','complete') AND (NOT EXISTS(SELECT 1 FROM public.admin_users WHERE user_id=r.user_id AND role=requested)
    OR NOT EXISTS(SELECT 1 FROM public."user" WHERE id=r.user_id AND email=r.email AND role='admin' AND status::text=
      CASE WHEN p_input->>'status'='inactive' THEN 'suspended' ELSE p_input->>'status' END)) THEN
    RAISE EXCEPTION 'Provisioned account changed; do not reactivate automatically';
  END IF;
  IF p_phase='persist' AND r.state='reserved' THEN
    IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=r.user_id AND lower(email)=r.email
       AND raw_app_meta_data->>'employee_provisioning_id'=r.user_id::text AND banned_until>now()) THEN
      RAISE EXCEPTION 'Owned, banned Auth identity required';
    END IF;
    IF EXISTS(SELECT 1 FROM public.rider WHERE user_id=r.user_id)
       OR EXISTS(SELECT 1 FROM public.organisation_membership WHERE user_id=r.user_id)
       OR EXISTS(SELECT 1 FROM public.admin_users WHERE user_id=r.user_id) THEN
      RAISE EXCEPTION 'Unexpected existing identity grants; investigation required';
    END IF;
    UPDATE public."user" SET name=p_input->>'name',phone=p_input->>'phone',
      status=(CASE WHEN p_input->>'status'='inactive' THEN 'suspended' ELSE p_input->>'status' END)::public.user_status,
      organization=p_input->>'organization',language_preference=p_input->>'languagePreference',
      is_verified=(p_input->>'isVerified')::boolean,email_verified=(p_input->>'isVerified')::boolean,verification_level='basic',
      account_notes=p_input->>'accountNotes',updated_at=now()
      WHERE id=r.user_id AND role='admin' AND status='pending';
    IF NOT FOUND THEN RAISE EXCEPTION 'Pending employee profile required'; END IF;
    INSERT INTO public.admin_users(user_id,email,role,created_by) VALUES(r.user_id,r.email,requested,p_actor);
    INSERT INTO public.platform_audit_record(actor_user_id,principal_type,capability,target_entity_type,target_entity_id,resulting_state,correlation_id,reason)
      VALUES(p_actor,'admin','users.manage','user',r.user_id::text,jsonb_build_object('role',requested,'status',p_input->>'status'),r.user_id::text,'admin_account_creation_v1');
    UPDATE public.employee_provisioning SET state='ready',updated_at=now() WHERE user_id=r.user_id RETURNING * INTO r;
  ELSIF p_phase='complete' AND r.state='ready' THEN
    IF p_input->>'status'='active' AND EXISTS(SELECT 1 FROM auth.users WHERE id=r.user_id AND banned_until>now()) THEN
      RAISE EXCEPTION 'Auth activation pending';
    END IF;
    UPDATE public.employee_provisioning SET state='complete',updated_at=now() WHERE user_id=r.user_id RETURNING * INTO r;
  END IF;
  RETURN jsonb_build_object('user_id',r.user_id,'state',r.state);
END $function$

CREATE OR REPLACE FUNCTION public.provision_product(p_actor uuid, p_id uuid, p_input jsonb, p_fingerprint text, p_phase text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE caps jsonb; identity auth.users; journal jsonb; requested text:=p_input->>'role'; required text; reservation public.product_provisioning;
BEGIN
  IF coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
  required:=CASE WHEN p_input ? 'waitlistId' THEN 'waitlist.manage' WHEN requested='advertiser' THEN 'advertisers.manage' ELSE 'users.manage' END;
  SELECT public.ops_employee_capabilities(a.role) INTO caps FROM public.admin_users a JOIN public."user" u ON u.id=a.user_id
    WHERE a.user_id=p_actor AND u.status='active';
  IF NOT coalesce(caps ? required,false) THEN RAISE EXCEPTION 'Unauthorized product provisioning' USING ERRCODE='42501'; END IF;
  IF requested IS NULL OR requested NOT IN ('rider','advertiser') OR p_input->>'status' IS NULL
    OR p_input->>'status' NOT IN ('active','inactive','pending') OR coalesce(btrim(p_input->>'name'),'')=''
    OR coalesce(p_input->>'email','') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
    OR p_input->>'email'<>lower(btrim(p_input->>'email')) OR length(p_fingerprint)<>64
    OR (requested='advertiser' AND (p_input->'advertiserProfile'->>'companyName' IS NULL OR p_input ? 'waitlistId'))
    OR (requested='rider' AND p_input ? 'advertiserProfile') OR p_input ?| ARRAY['organisationId','bundleKey','membershipRole'] THEN
    RAISE EXCEPTION 'Invalid product provisioning contract';
  END IF;
  IF p_phase IS NULL OR p_phase NOT IN ('validate','persist','complete') THEN RAISE EXCEPTION 'Invalid provisioning phase'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_input->>'email',68));
  IF EXISTS(SELECT 1 FROM auth.users WHERE lower(email)=p_input->>'email' AND id<>p_id) THEN
    RAISE EXCEPTION 'Email belongs to an existing account; use its authorized update workflow';
  END IF;
  IF p_input ? 'waitlistId' THEN
    PERFORM 1 FROM public.waitlist WHERE id=(p_input->>'waitlistId')::uuid AND lower(email)=p_input->>'email' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Waitlist identity mismatch'; END IF;
  END IF;
  SELECT * INTO reservation FROM public.product_provisioning WHERE user_id=p_id FOR UPDATE;
  IF reservation.user_id IS NULL THEN
    IF p_phase<>'validate' OR EXISTS(SELECT 1 FROM auth.users WHERE id=p_id) THEN RAISE EXCEPTION 'Product reservation required'; END IF;
    INSERT INTO public.product_provisioning(user_id,email,actor_id,input,fingerprint)
      VALUES(p_id,p_input->>'email',p_actor,p_input,p_fingerprint) RETURNING * INTO reservation;
  END IF;
  IF reservation.actor_id<>p_actor OR reservation.input<>p_input OR reservation.fingerprint<>p_fingerprint THEN
    RAISE EXCEPTION 'Conflicting product provisioning request';
  END IF;
  SELECT * INTO identity FROM auth.users WHERE id=p_id FOR UPDATE;
  journal:=identity.raw_app_meta_data->'admin_product_provisioning';
  IF identity.id IS NOT NULL AND (journal IS NULL OR journal->>'fingerprint' IS DISTINCT FROM p_fingerprint
      OR journal->>'actor' IS DISTINCT FROM p_actor::text) THEN
    RAISE EXCEPTION 'Conflicting product provisioning request';
  END IF;
  IF reservation.state IN ('ready','complete') THEN
    IF NOT EXISTS(SELECT 1 FROM public."user" WHERE id=p_id AND email=p_input->>'email' AND role::text=requested AND status::text=
      CASE WHEN p_input->>'status'='inactive' THEN 'suspended' ELSE p_input->>'status' END) THEN
      RAISE EXCEPTION 'Provisioned product account changed; do not reactivate automatically';
    END IF;
  END IF;
  IF p_phase='validate' THEN RETURN jsonb_build_object('id',p_id,'state',reservation.state); END IF;
  IF identity.id IS NULL THEN RAISE EXCEPTION 'Owned product Auth identity required'; END IF;
  IF reservation.state IN ('ready','complete') THEN
    IF p_phase='complete' AND reservation.state='ready' THEN
      IF p_input->>'status'='active' AND identity.banned_until>now() THEN RAISE EXCEPTION 'Auth activation pending'; END IF;
      UPDATE public.product_provisioning SET state='complete',updated_at=now() WHERE user_id=p_id;
    END IF;
    RETURN jsonb_build_object('id',p_id);
  END IF;
  IF p_phase<>'persist' OR reservation.state<>'reserved' OR identity.banned_until IS NULL OR identity.banned_until<=now()
    OR EXISTS(SELECT 1 FROM public.admin_users WHERE user_id=p_id)
    OR EXISTS(SELECT 1 FROM public.organisation_membership WHERE user_id=p_id)
    OR (requested='advertiser' AND EXISTS(SELECT 1 FROM public.rider WHERE user_id=p_id)) THEN
    RAISE EXCEPTION 'Invalid pending product identity';
  END IF;
  UPDATE public."user" SET name=p_input->>'name',phone=p_input->>'phone',organization=p_input->>'organization',
    status=(CASE WHEN p_input->>'status'='inactive' THEN 'suspended' ELSE p_input->>'status' END)::public.user_status,
    language_preference=p_input->>'languagePreference',is_verified=(p_input->>'isVerified')::boolean,
    email_verified=coalesce((p_input->>'emailVerified')::boolean,(p_input->>'isVerified')::boolean),verification_level='basic',account_notes=p_input->>'accountNotes',updated_at=now()
    WHERE id=p_id AND role::text=requested AND status='pending';
  IF NOT FOUND THEN RAISE EXCEPTION 'Pending product profile required'; END IF;
  IF requested='rider' THEN
    UPDATE public.rider SET city=coalesce(p_input->>'city',city),country=coalesce(p_input->>'country',country),
      status=CASE WHEN p_input->>'status'='active' THEN 'active'::public.rider_status ELSE 'inactive'::public.rider_status END
      WHERE user_id=p_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Rider profile missing'; END IF;
  ELSE
    UPDATE public.advertiser SET company_name=p_input->'advertiserProfile'->>'companyName',company_email=p_input->>'email',
      website=p_input->'advertiserProfile'->>'website',logo_url=p_input->'advertiserProfile'->>'logoUrl',
      industry=p_input->'advertiserProfile'->>'industry',language=p_input->'advertiserProfile'->>'language',
      timezone=p_input->'advertiserProfile'->>'timezone',budget=(p_input->'advertiserProfile'->>'budget')::numeric,
      email_notifications=(p_input->'advertiserProfile'->>'emailNotifications')::boolean,
      campaign_updates=(p_input->'advertiserProfile'->>'campaignUpdates')::boolean WHERE user_id=p_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Advertiser profile missing'; END IF;
  END IF;
  IF p_input ? 'waitlistId' THEN
    UPDATE public.waitlist SET converted_to_user=true,status='approved',status_reason=p_input->>'waitlistReason',
      provisioning_user_id=p_id,updated_at=now() WHERE id=(p_input->>'waitlistId')::uuid;
  END IF;
  UPDATE public.product_provisioning SET state='ready',updated_at=now() WHERE user_id=p_id;
  INSERT INTO public.platform_audit_record(actor_user_id,principal_type,capability,target_entity_type,target_entity_id,resulting_state,correlation_id,reason)
    VALUES(p_actor,'admin',required,'user',p_id::text,jsonb_build_object('role',requested,'status',p_input->>'status'),p_id::text,'admin_account_creation_v1');
  RETURN jsonb_build_object('id',p_id);
END $function$

CREATE OR REPLACE FUNCTION public.set_account_deletion_intake(p_state text, p_expected bigint, p_reason text, p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE actor uuid; gate public.account_deletion_contract_gate; prior public.ops_command_receipt;
 payload jsonb; result jsonb; old_state jsonb;
BEGIN
 actor:=public.ops_assert_capability('settings.security');
 IF NOT EXISTS(SELECT 1 FROM public.admin_users WHERE user_id=actor AND role::text IN ('super_admin','security_admin')) THEN
  RAISE EXCEPTION 'Security administrator required' USING ERRCODE='42501'; END IF;
 IF p_state IS NULL OR p_state NOT IN ('enabled','disabled','hold') OR p_expected IS NULL OR p_expected<0 OR p_operation IS NULL
 OR length(trim(coalesce(p_reason,''))) NOT BETWEEN 10 AND 1000 THEN
  RAISE EXCEPTION 'State, version, operation and reason required' USING ERRCODE='22023'; END IF;
 payload:=jsonb_build_object('state',p_state,'expected',p_expected,'reason',trim(p_reason));
 SELECT * INTO gate FROM public.account_deletion_contract_gate WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Intake control unavailable' USING ERRCODE='55000'; END IF;
 SELECT * INTO prior FROM public.ops_command_receipt WHERE actor_user_id=actor AND operation=p_operation;
 IF FOUND THEN
  IF prior.kind<>'deletion.intake' OR prior.payload<>payload THEN RAISE EXCEPTION 'Operation reused' USING ERRCODE='22023'; END IF;
  RETURN prior.result;
 END IF;
 IF gate.operating_version<>p_expected THEN RAISE EXCEPTION 'Operating state changed' USING ERRCODE='40001'; END IF;
 IF p_state='enabled' AND NOT public.account_deletion_intake_ready(gate.active_policy_version) THEN
  RAISE EXCEPTION 'Intake contract and approved receipt access required' USING ERRCODE='55000'; END IF;
 old_state:=jsonb_build_object('state',gate.operating_state,'version',gate.operating_version);
 UPDATE public.account_deletion_contract_gate SET operating_state=p_state,operating_version=operating_version+1,
  operating_changed_at=clock_timestamp(),operating_changed_by=actor,operating_reason=trim(p_reason) WHERE singleton;
 result:=public.account_deletion_intake_status();
 PERFORM public.ops_audit('settings.security','account_deletion_intake','global',old_state,result,trim(p_reason),p_operation);
 INSERT INTO public.ops_command_receipt(actor_user_id,operation,kind,payload,result) VALUES(actor,p_operation,'deletion.intake',payload,result);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.shop_authorize(p_actor uuid, p_action text, p_org uuid DEFAULT NULL::uuid, p_rider uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role text; BEGIN
 IF p_actor IS NULL THEN RAISE EXCEPTION 'Actor required' USING ERRCODE='42501'; END IF;
 IF p_action='redeem' AND EXISTS(SELECT 1 FROM rider WHERE id=p_rider AND user_id=p_actor) THEN RETURN 'rider'; END IF;
 SELECT role INTO v_role FROM admin_users WHERE user_id=p_actor;
 IF v_role IS NOT NULL AND (
  (p_action='read' AND v_role IN ('super_admin','admin','operations_manager','partner_operations_manager','support_agent','support_lead','security_admin')) OR
  (p_action IN ('cancel','refund','consume','collect','adjust','retry') AND v_role IN ('super_admin','admin','operations_manager','partner_operations_manager'))
 ) THEN RETURN 'admin'; END IF;
 IF p_action='read' AND EXISTS(SELECT 1 FROM rider WHERE id=p_rider AND user_id=p_actor) THEN RETURN 'rider'; END IF;
 IF p_org IS NOT NULL AND EXISTS(SELECT 1 FROM organisation_membership WHERE user_id=p_actor AND organisation_id=p_org AND status='active'
  AND ((p_action='read') OR (p_action IN ('consume','collect') AND role IN ('owner','manager','staff')) OR
  (p_action IN ('cancel','refund','retry') AND role IN ('owner','manager')))) THEN RETURN 'organisation'; END IF;
 RAISE EXCEPTION 'Target not authorized' USING ERRCODE='42501';
END $function$

CREATE OR REPLACE FUNCTION public.update_admin_user_profile(p_actor uuid, p_user uuid, p_role text, p_patch jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE caps jsonb;
BEGIN
  IF coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
  SELECT public.ops_employee_capabilities(a.role) INTO caps FROM public.admin_users a JOIN public."user" u ON u.id=a.user_id WHERE a.user_id=p_actor AND u.status='active';
  IF NOT coalesce(caps ? 'users.manage',false) THEN RAISE EXCEPTION 'Unauthorized profile update' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public."user" WHERE id=p_user FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'User not found'; END IF;
  IF p_role IS NOT NULL THEN PERFORM public.assign_employee_role(p_actor,p_user,p_role); END IF;
  UPDATE public."user" SET
    name=CASE WHEN p_patch ? 'name' THEN p_patch->>'name' ELSE name END,
    email=CASE WHEN p_patch ? 'email' THEN p_patch->>'email' ELSE email END,
    phone=CASE WHEN p_patch ? 'phone' THEN p_patch->>'phone' ELSE phone END,
    status=CASE WHEN p_patch ? 'status' THEN (p_patch->>'status')::public.user_status ELSE status END,
    organization=CASE WHEN p_patch ? 'organization' THEN p_patch->>'organization' ELSE organization END,
    language_preference=CASE WHEN p_patch ? 'language_preference' THEN p_patch->>'language_preference' ELSE language_preference END,
    is_verified=CASE WHEN p_patch ? 'is_verified' THEN (p_patch->>'is_verified')::boolean ELSE is_verified END,
    account_notes=CASE WHEN p_patch ? 'account_notes' THEN p_patch->>'account_notes' ELSE account_notes END,
    updated_at=now() WHERE id=p_user;
  -- Employee email is presentation data; preserve its exact role template.
  IF p_patch ? 'email' THEN UPDATE public.admin_users SET email=p_patch->>'email',updated_at=now() WHERE user_id=p_user; END IF;
END $function$
